import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import * as Dialog from "@radix-ui/react-dialog";
import { Button } from "./button";

// KMP-C26 (specs/KMP-C26-regenerate-sheet.md). Radix Dialog (modal) as a bottom sheet with NO overlay: dimming is opacity, which is banned.
// Radix makes the page behind inert; pointer presses outside do nothing; Escape and Keep this plan close with nothing changed.
// Focus opens on Keep this plan (the safe action) and returns to the opener. The consumer announces after regenerating.

export type RegenerateSheetProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Regenerate was chosen. The sheet then closes. Idempotence is the consumer's. */
  onConfirm: () => void;
  /** Slots the user changed in next week. 0 or missing: the second sentence is absent. */
  changedCount?: number;
  /** Wording of the second sentence (singular form is the planner's, Q-G4). */
  changedSentence?: (count: number) => ReactNode;
};

export const REGENERATE_TITLE = "Replace next week's plan?";

export function RegenerateSheet({
  open,
  onOpenChange,
  onConfirm,
  changedCount = 0,
  changedSentence = (n) => `${n} dishes you chose will be replaced too.`,
}: RegenerateSheetProps) {
  const keep = useRef<HTMLButtonElement>(null);
  const opener = useRef<HTMLElement | null>(null);
  const titleId = useId();
  // Page scroll lock while open (no overlay exists, so Radix' own lock does not apply). The page scrollbar's width is
  // compensated so nothing shifts; the scroll position is untouched and everything is released on close and unmount.
  useEffect(() => {
    if (!open) return;
    const body = document.body;
    const gutter = window.innerWidth - document.documentElement.clientWidth;
    const before = { overflow: body.style.overflow, paddingRight: body.style.paddingRight };
    body.style.overflow = "hidden";
    if (gutter > 0) body.style.paddingRight = `calc(${getComputedStyle(body).paddingRight} + ${gutter}px)`;
    return () => {
      body.style.overflow = before.overflow;
      body.style.paddingRight = before.paddingRight;
    };
  }, [open]);

  // Scroll region: a tab stop only while it overflows. If the space left for it (max height minus the footer) is below its
  // minimum (2 x control height), the footer unpins and the whole sheet below the top edge scrolls as one area (spec 6.1).
  const observer = useRef<ResizeObserver | null>(null);
  const [sheet, setSheet] = useState<HTMLDivElement | null>(null);
  const [region, setRegion] = useState<HTMLDivElement | null>(null);
  const [footer, setFooter] = useState<HTMLDivElement | null>(null);
  const [overflowing, setOverflowing] = useState(false);
  const [unpinned, setUnpinned] = useState(false);
  const measure = useCallback(() => {
    if (!sheet || !region || !footer) return;
    const cs = getComputedStyle(sheet);
    const chrome = ["paddingTop", "paddingBottom", "borderTopWidth", "borderBottomWidth"].reduce((n, k) => n + (parseFloat(cs[k as "paddingTop"]) || 0), 0);
    const left = parseFloat(cs.maxHeight) - chrome - footer.offsetHeight; // NaN without a layout engine or max height: stays pinned
    const loose = left < (parseFloat(getComputedStyle(region).minHeight) || 0);
    setUnpinned(loose);
    setOverflowing(!loose && region.scrollHeight > region.clientHeight + 1);
  }, [sheet, region, footer]);
  // Unpinned, the sheet itself scrolls. Open-focus runs before that layout settles and Radix' focus trap wraps with preventScroll,
  // so bring the focused element into view when the layout changes and on every focus move inside the sheet.
  const reveal = useCallback(() => {
    const el = document.activeElement;
    if (unpinned && el instanceof HTMLElement && sheet?.contains(el)) el.scrollIntoView({ block: "nearest" });
  }, [unpinned, sheet]);
  useLayoutEffect(() => {
    if (open) reveal();
  }, [open, unpinned, reveal]);
  useLayoutEffect(() => {
    measure();
    if (!sheet || typeof ResizeObserver === "undefined") return;
    observer.current = new ResizeObserver(measure);
    for (const el of [sheet, region, footer]) if (el) observer.current.observe(el);
    window.addEventListener("resize", measure);
    return () => {
      observer.current?.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [sheet, region, footer, measure, changedCount]);
  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Content
          ref={setSheet}
          aria-modal="true"
          aria-labelledby={titleId}
          onFocusCapture={reveal}
          onOpenAutoFocus={(e) => {
            e.preventDefault();
            opener.current = document.activeElement as HTMLElement | null; // still the control that opened the sheet
            if (region) region.scrollTop = 0; // scroll resets to the top on every open
            keep.current?.focus(); // initial focus stays on the safe, pinned action
          }}
          onCloseAutoFocus={(e) => {
            e.preventDefault();
            opener.current?.focus(); // focus returns to the opener (there is no Dialog.Trigger: the consumer controls open)
          }}
          onPointerDownOutside={(e) => e.preventDefault()}
          onInteractOutside={(e) => e.preventDefault()}
          className={[
            "fixed inset-x-0 bottom-0 z-modal flex flex-col overflow-y-auto overscroll-contain",
            "rounded-t-control border-x-bw-default border-b-bw-default border-t-bw-heavy border-x-border-card border-b-border-card border-t-border-strong bg-surface-raised px-inset-md pt-inset-md font-body leading-normal",
            // Max height: dynamic viewport height (ordinary vh as fallback) minus the top inset minus space.inset.lg. No fixed fraction.
            "max-h-[calc(100vh_-_env(safe-area-inset-top)_-_var(--shamallya-semantic-space-inset-lg))]",
            "supports-[height:100dvh]:max-h-[calc(100dvh_-_env(safe-area-inset-top)_-_var(--shamallya-semantic-space-inset-lg))]",
          ].join(" ")}
        >
          <div
            ref={setRegion}
            {...(overflowing ? { tabIndex: 0, role: "region", "aria-labelledby": titleId } : {})}
            className={[
              "flex min-h-[calc(2_*_var(--shamallya-semantic-size-control-height))] flex-col gap-stack-md pb-stack-md",
              unpinned ? "flex-none" : "flex-1 overflow-y-auto overscroll-contain",
            ].join(" ") + " focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring-inside focus-visible:outline-focus-ring"}
          >
            <Dialog.Title id={titleId} className="text-ui-subtitle font-semibold text-text [overflow-wrap:anywhere]">
              {REGENERATE_TITLE}
            </Dialog.Title>
            <Dialog.Description className="text-ui-reading font-regular text-text-muted [overflow-wrap:anywhere]">
              This plans all seven days again.
              {changedCount > 0 && <> {changedSentence(changedCount)}</>}
            </Dialog.Description>
          </div>
          <div ref={setFooter} className="flex shrink-0 flex-col gap-stack-sm border-t-bw-default border-border-subtle pb-[calc(env(safe-area-inset-bottom)+var(--shamallya-semantic-space-inset-sm))] pt-inset-sm">
            <Button
              variant="primary"
              fullWidth
              onClick={() => {
                onConfirm();
                onOpenChange(false);
              }}
            >
              Regenerate
            </Button>
            <Button ref={keep} variant="outline" fullWidth onClick={() => onOpenChange(false)}>
              Keep this plan
            </Button>
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
